const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let num = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            num = num * 10 + (buffer[offset] - 48);
            offset++;
        }
        return sign * num;
    }

    const n = readInt();
    if (n === null) return;

    const x = new Int32Array(n + 1);
    const y = new Int32Array(n + 1);

    // O Palácio Real é o índice 0 com coordenadas (0, 0)
    x[0] = 0;
    y[0] = 0;

    for (let i = 1; i <= n; i++) {
        x[i] = readInt();
        y[i] = readInt();
    }

    // Número de arestas entre tendas: n * (n - 1) / 2
    // Número de arestas entre o palácio e tendas: n
    // Total de arestas: n * (n + 1) / 2
    const m = (n * (n + 1)) >> 1;

    const uArr = new Uint16Array(m);
    const vArr = new Uint16Array(m);
    const dArr = new Int32Array(m);

    let edgeCount = 0;

    // Arestas do Palácio para tendas
    for (let i = 1; i <= n; i++) {
        const dx = x[i];
        const dy = y[i];
        uArr[edgeCount] = 0;
        vArr[edgeCount] = i;
        dArr[edgeCount] = dx * dx + dy * dy;
        edgeCount++;
    }

    // Arestas entre tendas
    for (let i = 1; i <= n; i++) {
        const xi = x[i];
        const yi = y[i];
        for (let j = i + 1; j <= n; j++) {
            const dx = xi - x[j];
            const dy = yi - y[j];
            uArr[edgeCount] = i;
            vArr[edgeCount] = j;
            dArr[edgeCount] = dx * dx + dy * dy;
            edgeCount++;
        }
    }

    // Ordenação das arestas por distância usando Radix Sort (32-bit unsigned/positive)
    let p = new Int32Array(m);
    for (let i = 0; i < m; i++) p[i] = i;

    let pNext = new Int32Array(m);
    const count = new Int32Array(256);

    for (let shift = 0; shift < 32; shift += 8) {
        count.fill(0);
        for (let i = 0; i < m; i++) {
            const byte = (dArr[p[i]] >>> shift) & 0xFF;
            count[byte]++;
        }
        for (let i = 1; i < 256; i++) {
            count[i] += count[i - 1];
        }
        for (let i = m - 1; i >= 0; i--) {
            const idx = p[i];
            const byte = (dArr[idx] >>> shift) & 0xFF;
            count[byte]--;
            pNext[count[byte]] = idx;
        }
        const tmp = p;
        p = pNext;
        pNext = tmp;
    }

    // dp[i] armazena o tamanho máximo do caminho estritamente decrescente
    // que inicia na tenda i considerando apenas arestas de comprimento menor
    const dp = new Int16Array(n + 1);
    const maxDp = new Int16Array(n + 1);
    for (let i = 1; i <= n; i++) maxDp[i] = dp[i];

    let maxCandies = 0;

    let i = 0;
    while (i < m) {
        let j = i;
        const currentDist = dArr[p[i]];
        while (j < m && dArr[p[j]] === currentDist) {
            j++;
        }

        // Processar todas as arestas com a mesma distância
        for (let k = i; k < j; k++) {
            const edgeIdx = p[k];
            const u = uArr[edgeIdx];
            const v = vArr[edgeIdx];

            if (u === 0) {
                // Aresta do palácio para v
                const candies = 1 + dp[v];
                if (candies > maxCandies) {
                    maxCandies = candies;
                }
            } else {
                // Aresta entre tendas u e v
                const candU = dp[v] + 1;
                const candV = dp[u] + 1;

                if (candU > maxDp[u]) maxDp[u] = candU;
                if (candV > maxDp[v]) maxDp[v] = candV;
            }
        }

        // Atualizar os valores de dp após processar o grupo de mesma distância
        for (let k = i; k < j; k++) {
            const edgeIdx = p[k];
            const u = uArr[edgeIdx];
            const v = vArr[edgeIdx];

            if (u !== 0) {
                dp[u] = maxDp[u];
                dp[v] = maxDp[v];
            }
        }

        i = j;
    }

    console.log(maxCandies);
}

solve();
